from fractions import Fraction as F
best = 0
for i in range(1, 60):
    for j in range(1, 60):
        a, b = F(i, 10), F(j, 10)
        c = 6 - a - b
        if c > 0:
            best = max(best, a*b*c)
assert best == 8
print(best)

from fractions import Fraction as F
best = None
for i in range(1, 180):
    for j in range(1, 180):
        a, b = F(i, 60), F(j, 60)
        c = 3 - a - b
        if c > 0:
            v = 1/a + 4/b + 9/c
            if best is None or v < best:
                best = v
assert best == 12
print(best)

from fractions import Fraction as F
best = 0
for k in range(1, 60):
    for j in range(1, 60 - k):
        x, y = F(k, 10), F(j, 10)
        z = 6 - x - y
        if z > 0:
            best = max(best, x*x*y**3*z)
assert best == 108
print(best)

from fractions import Fraction as F
count = 0
for x in range(1, 50):
    for y in range(x, 200):
        r = 1 - F(1, x) - F(1, y)
        if r > 0 and r.numerator == 1 and r.denominator >= y:
            count += 1
print(count)

from fractions import Fraction as F
best = None
for i in range(1, 60):
    for j in range(1, 60):
        a, b = F(i, 60), F(j, 60)
        c = 1 - a - b
        if c > 0:
            v = a*a/(b + c) + b*b/(c + a) + c*c/(a + b)
            if best is None or v < best:
                best = v
assert best == F(1, 2)
print(best)

